const body=$input.first().json.body??$input.first().json;
if(!["SUBSCRIPTION_INVOICE_CREATED","SUBSCRIPTION_PAYMENT_CONFIRMED","SUBSCRIPTION_REMINDER"].includes(body.eventType))throw Error("Evento desconhecido");
if(!/^[a-zA-Z0-9_-]{8,200}$/.test(String(body.eventId||"")))throw Error("ID inválido");
const email=String(body.toEmail||"").trim(),phone=String(body.toWhatsApp||"").replace(/\D/g,"");
if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||phone.length<10||phone.length>13)throw Error("Destino inválido");
const name=String(body.planName||"Plano Dishy").slice(0,80),value=(Number(body.priceCents||0)/100).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
const paid=body.eventType==="SUBSCRIPTION_PAYMENT_CONFIRMED";
const due=typeof body.dueAtMs==="number"?new Date(body.dueAtMs).toLocaleDateString("pt-BR",{timeZone:"America/Sao_Paulo"}):"";
const renew=body.periodEndAt?new Date(body.periodEndAt).toLocaleDateString("pt-BR",{timeZone:"America/Sao_Paulo"}):"";
let title="",message="";
if(paid){title="Pagamento confirmado — Dishy";message="Recebemos o pagamento de "+value+" do plano "+name+". Seu acesso foi atualizado. Próximo vencimento: "+renew+".";}
else if(body.eventType==="SUBSCRIPTION_REMINDER"){
 const day=Number(body.daysToDue);
 const label=day>0?"faltam "+day+" dias para vencer":day===0?"vence hoje":"está em atraso há "+Math.abs(day)+" dia(s)";
 title="Aviso de mensalidade — Dishy";
 message="Sua mensalidade do plano "+name+" ("+value+") "+label+". Vencimento: "+due+". Pagamento por PIX ou cartão: "+String(body.paymentUrl||"");
}else{
 title="Mensalidade disponível — Dishy";
 message="Sua mensalidade do plano "+name+" ("+value+") está disponível. Pague com PIX ou cartão pelo link: "+String(body.paymentUrl||"")+". Não há débito automático.";
}
message+="\n\nAcompanhe seu contrato e pagamentos em https://dishy.com.br/login (Meu plano).\nSe já pagou, aguarde a confirmação automática.";
return [{json:{eventId:body.eventId,toEmail:email,toWhatsApp:phone.startsWith("55")?phone:"55"+phone,subject:title,emailText:message,whatsappText:message}}];
